/**
 * The Mercator projection the coastlines above were drawn with, recovered by
 * fitting Natural Earth country bounds to these paths (error under 1 unit).
 * Place anything on the map with real coordinates through this, never by eye.
 */
const MERCATOR = { scale: 1549.05, x: 340.74, y: 2089.43 };

/** Real latitude/longitude (degrees) to map units in `europeView`. */
export function projectToMap(lat: number, lon: number): { x: number; y: number } {
  const rad = Math.PI / 180;
  return {
    x: MERCATOR.x + MERCATOR.scale * lon * rad,
    y: MERCATOR.y - MERCATOR.scale * Math.log(Math.tan(Math.PI / 4 + (lat * rad) / 2)),
  };
}

/** Real latitude/longitude to a percent of the map, for absolutely placed pins. */
export function mapPin(lat: number, lon: number): { x: number; y: number } {
  const { x, y } = projectToMap(lat, lon);
  return {
    x: Math.round((x / europeView.width) * 1000) / 10,
    y: Math.round((y / europeView.height) * 1000) / 10,
  };
}

/**
 * Cartoon landmarks drawn on the map, centred on real coordinates. Landmarks for
 * pinned cities (Big Ben, Sagrada Família, the Lisbon tram) sit inside their pins.
 */
const landmarkSpots: { id: string; lat: number; lon: number; scale?: number }[] = [
  { id: "eiffel", lat: 48.858, lon: 2.294 }, // Eiffel Tower, Paris
  { id: "windmill", lat: 52.474, lon: 4.818, scale: 0.55 }, // Zaanse Schans windmills
  { id: "gate", lat: 52.516, lon: 13.378, scale: 1.2 }, // Brandenburg Gate, Berlin
  { id: "tower", lat: 43.85, lon: 10.95, scale: 1.3 }, // Leaning Tower, nudged inland from Pisa so it stays on land
];

export const europeLandmarks: { id: string; x: number; y: number; scale?: number }[] = landmarkSpots.map(
  ({ id, lat, lon, scale }) => {
    const { x, y } = projectToMap(lat, lon);
    return { id, x: Math.round(x * 10) / 10, y: Math.round(y * 10) / 10, scale };
  },
);
